fn scale() -> i32 {
    8
}

fn fall(v: i32) -> i32 {
    v + 2
}

fn step(p: i32, v: i32) -> i32 {
    p + v
}

fn floor_bounce(p: i32, v: i32, floor: i32) -> i32 {
    if p >= floor {
        if v > 0 { (0 - v) / 2 } else { v }
    } else {
        v
    }
}

fn dims() -> i32 {
    (256 << 16) | 96
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB PHYS8", 0xffffff, 2);
    host::display::draw_string(8, 32, "SCALE FALL STEP", 0x00ff66, 1);
    host::display::draw_string(8, 46, "FLOOR_BOUNCE", 0x00ff66, 1);
    host::display::draw_string(8, 60, "1 PX = 8 UNITS", 0x808080, 1);
    host::display::present();
}
